code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    lines = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2-r1, c2-c1
            if abs(dr) == abs(dc) and dr != 0:
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                cells = [(r1 + k*sr, c1 + k*sc) for k in range(abs(dr)+1)]
                lines.append((set(cells), sc * sr))
                for r, c in cells:
                    if out[r][c] != 6:
                        out[r][c] = 1
    for r, c in sixes:
        for cells, slope in lines:
            if (r, c) not in cells:
                continue
            # Extend a diagonal through the six, perpendicular to the one-line.
            step_c = -slope
            for k in range(-h, h+w+1):
                rr, cc = r+k, c+k*step_c
                if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 1:
                    out[rr][cc] = 6
    return out
'''
